// One-off (run from the repository root, do not commit): parse release.yaml and list every push-main call site.
const text = await Bun.file(".github/workflows/release.yaml").text();
const doc = Bun.YAML.parse(text) as { jobs: Record<string, { steps?: { name?: string; run?: string }[] }> };
for (const [job, spec] of Object.entries(doc.jobs)) {
  for (const step of spec.steps ?? []) {
    if (/push-main/.test(step.run ?? "")) console.log(`${job}: ${step.name}: ${step.run?.trim()}`);
  }
}
